const results=[];
const repair=(root)=>{
  const stack=[root];
  while(stack.length){
    const n=stack.pop();
    if('children'in n)stack.push(...n.children);
    if(n.type==='FRAME'&&n.layoutMode==='VERTICAL'&&n.primaryAxisSizingMode==='FIXED'&&n.height<=120){
      n.primaryAxisSizingMode='AUTO';results.push('fixed V '+n.name+' h='+Math.round(n.height));
    }
  }
};
